<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {setUser,safeNext} from '../auth'
const route=useRoute(),router=useRouter(),register=computed(()=>route.path==='/register')
const username=ref(''),password=ref(''),confirmation=ref(''),invite=ref(''),busy=ref(false),error=ref(''),show=ref(false)
watch(register,()=>{error.value='';password.value='';confirmation.value='';show.value=false})
async function submit(){
 error.value=''
 if(register.value&&password.value!==confirmation.value){error.value='两次输入的密码不一致';return}
 busy.value=true
 try{
  const response=await fetch('/api/auth/'+(register.value?'register':'login'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value,invite:invite.value.trim()})})
  const data=await response.json()
  if(!response.ok)throw new Error(data.message||'操作失败，请稍后重试')
  setUser(data.user);password.value='';confirmation.value='';await router.replace(safeNext(route.query.next))
 }catch(e){error.value=e.message||'无法连接服务，请稍后重试'}finally{busy.value=false}
}
</script>
<template><main class="auth-page"><section class="auth-story"><div class="auth-brand">yangbin <span>AI</span></div><div class="story-copy"><div class="eyebrow">YOUR PERSONAL AI WORKSPACE</div><h1>把想法<br>变成下一步。</h1><p>从有据可查的回答，到可以调整的约会方案。<br>你的资料与计划，保存在自己的账号中。</p><div class="story-tags"><span>知识库 RAG</span><span>MCP 工具</span><span>约会规划</span></div></div><small>为认真相处，也为认真思考。</small></section><section class="auth-form-wrap"><div class="auth-form"><span class="auth-kicker">{{register?'INVITATION ONLY':'WELCOME BACK'}}</span><h2>{{register?'创建你的账号':'欢迎回来'}}</h2><p class="auth-description">{{register?'使用管理员提供的邀请码，开启你的个人工作台。':'登录后，继续你的对话、知识库和计划。'}}</p><div v-if="error" class="auth-error" role="alert">{{error}}</div><div v-if="route.query.changed" class="auth-success">密码已更新，请重新登录。</div><form @submit.prevent="submit"><label>用户名<input v-model="username" autocomplete="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_-]{3,32}" placeholder="字母、数字、下划线或短横线" :disabled="busy"></label><label>密码<div class="password-field"><input v-model="password" :type="show?'text':'password'" :autocomplete="register?'new-password':'current-password'" required :minlength="register?10:1" maxlength="128" :placeholder="register?'至少 10 个字符':'输入密码'" :disabled="busy"><button type="button" @click="show=!show" :aria-label="show?'隐藏密码':'显示密码'">{{show?'隐藏':'显示'}}</button></div></label><template v-if="register"><label>确认密码<input v-model="confirmation" type="password" autocomplete="new-password" required minlength="10" maxlength="128" :disabled="busy"></label><label>邀请码<input v-model="invite" required maxlength="100" autocomplete="off" placeholder="向管理员获取邀请码" :disabled="busy"></label></template><button class="auth-submit" :disabled="busy">{{busy?'正在处理…':register?'注册并进入工作台':'登录'}}</button></form><p class="auth-switch">{{register?'已经有账号？':'还没有账号？'}} <RouterLink :to="{path:register?'/login':'/register',query:route.query.next?{next:route.query.next}:{}}">{{register?'去登录':'使用邀请码注册'}}</RouterLink></p><p class="auth-note">{{register?'邀请码可能有次数和有效期限制，注册后无法查看其他用户的私有资料。':'忘记密码请联系管理员。原有账号可使用之前的用户名与口令登录。'}}</p></div></section></main></template>
<style scoped>.auth-page{min-height:100vh;display:grid;grid-template-columns:1fr 1fr;background:#f7fafb;color:#213c4a}.auth-story{padding:42px 10%;background:radial-gradient(ellipse at 15% 85%,#286459 0%,transparent 55%),#142c3a;display:flex;flex-direction:column;color:#d1e5e3;min-height:100vh}.auth-brand{font-size:26px;font-weight:750;color:white}.auth-brand span{color:#86d6c4}.story-copy{margin:auto 0;padding:80px 0}.eyebrow{font-size:11px;letter-spacing:2px;color:#92beb7}.story-copy h1{font-size:60px;line-height:1.25;letter-spacing:-2px;font-weight:650;color:#fff;margin:22px 0 28px}.story-copy p{font-size:15px;line-height:2;color:#b4ccca}.story-tags{display:flex;gap:10px;flex-wrap:wrap;margin-top:35px}.story-tags span{font-size:12px;border:1px solid #5d7c7b;border-radius:20px;padding:7px 12px}.auth-story small{font-size:12px;color:#9bbdb7}.auth-form-wrap{display:flex;align-items:center;justify-content:center;padding:45px 30px}.auth-form{width:100%;max-width:370px}.auth-kicker{font-size:10px;letter-spacing:2px;font-weight:700;color:#6a8c91}.auth-form h2{font-size:32px;margin:12px 0}.auth-description{font-size:14px;line-height:1.8;color:#6d828b;margin-bottom:27px}.auth-form label{display:block;margin:18px 0;font-size:13px;font-weight:600}.auth-form input{width:100%;display:block;border:1px solid #cbd9de;background:white;border-radius:9px;padding:13px;margin-top:8px;font:inherit;font-weight:400;color:#213c4a;min-width:0}.auth-form input:focus{outline:2px solid #81bfb3;outline-offset:1px}.password-field{position:relative}.password-field input{padding-right:60px}.password-field button{position:absolute;right:8px;top:9px;padding:6px;border:0;background:none;color:#5e7d83;font-size:12px}.auth-submit{width:100%;padding:14px;border:0;border-radius:9px;background:#196f69;color:white;font-weight:650;margin-top:10px;font-size:15px}.auth-submit:disabled{opacity:.6;cursor:wait}.auth-switch{text-align:center;font-size:13px;color:#6d828b;margin-top:24px}.auth-switch a{color:#196f69;font-weight:650}.auth-note{font-size:12px;color:#8a9da5;line-height:1.8;margin-top:24px}.auth-error,.auth-success{padding:12px;border-radius:8px;font-size:13px;line-height:1.6}.auth-error{background:#fff0ed;color:#a84432}.auth-success{background:#e6f4ed;color:#286f53}@media(max-width:800px){.auth-page{grid-template-columns:1fr}.auth-story{min-height:auto;padding:23px 25px}.story-copy,.auth-story small{display:none}.auth-form-wrap{padding:36px 24px}.auth-form h2{font-size:28px}}</style>
